ypes":["factual_assertion"],"evidence_ids":[2]},{"claim_text":"Public housing should remain a core element of housing policy.", "claim_types":["policy_position"],"evidence_ids":[2]},{"claim_text":"All public housing units should be replaced with new units at no less than a one-to-one basis.", "claim_types":["policy_position"],"evidence_ids":[2]}],"unresolved_references":[]}
